"""SYNTHETIC Data Generator for Queue-Based Matchmaking.

DISCLAIMER: All player attributes, skill distributions, wait times,
network pings, and arrival sequences generated by this module are purely
SYNTHETIC and generated from stochastic distributions. No real player traces
or proprietary dataset sources are used.
"""
from __future__ import annotations

from typing import Any
import numpy as np

from mm.config import load_config
from mm.types import Instance, Player

# Preset player counts for scenarios
SCENARIOS: dict[str, int] = {
    "light": 24,
    "medium": 100,
    "heavy": 400,
}

# Role definitions: 0: Tank, 1: DPS, 2: Support
ROLES = [0, 1, 2]
ROLE_PROBABILITIES = [0.2, 0.5, 0.3]


def make_instance(
    n_players: int | None = None,
    k: int | None = None,
    seed: int = 42,
    scenario: str = "medium",
    **kw: Any,
) -> Instance:
    """Generate a SYNTHETIC Matchmaking queue instance.

    All data produced by this generator is SYNTHETIC and stochastic.

    Parameters
    ----------
    n_players : int | None
        Number of queued players. If None, inferred from `scenario`.
    k : int | None
        Number of players per team in a match (2k total players per match).
        If None, loaded from configuration.
    seed : int
        RNG seed for deterministic instance reproduction.
    scenario : str
        Queue load scenario ("light", "medium", "heavy").
    **kw : Any
        Optional overrides for dt, max_wait, gap0, gap_alpha, include_roles, include_ping.

    Returns
    -------
    Instance
        SYNTHETIC Instance containing generated players and parameters.
    """
    cfg = load_config()

    if n_players is None:
        scenario_lower = scenario.lower()
        if scenario_lower in SCENARIOS:
            n_players = SCENARIOS[scenario_lower]
        elif hasattr(cfg.queue_sizes, scenario_lower):
            n_players = getattr(cfg.queue_sizes, scenario_lower)
        else:
            n_players = 100

    match_k = k if k is not None else cfg.k
    dt = float(kw.get("dt", cfg.dt))
    max_wait = float(kw.get("max_wait", cfg.max_wait))
    gap0 = float(kw.get("gap0", cfg.gap0))
    gap_alpha = float(kw.get("gap_alpha", cfg.gap_alpha))
    include_roles = bool(kw.get("include_roles", True))
    include_ping = bool(kw.get("include_ping", True))

    rng = np.random.default_rng(seed)

    if n_players <= 0:
        return Instance(
            players=[],
            k=match_k,
            dt=dt,
            max_wait=max_wait,
            gap0=gap0,
            gap_alpha=gap_alpha,
            seed=seed,
        )

    # 1. Skill ~ Normal(1500, 300) (Elo-like, clipped to >= 100)
    skills = rng.normal(loc=1500.0, scale=300.0, size=n_players)
    skills = np.maximum(100.0, skills)

    # 2. Wait times ~ Exponential(scale=30.0)
    waits = rng.exponential(scale=30.0, size=n_players)

    # 3. Poisson arrivals: cumulative exponential inter-arrivals
    inter_arrivals = rng.exponential(scale=5.0, size=n_players)
    arrivals = np.cumsum(inter_arrivals)

    # 4. Roles: 0 = Tank, 1 = DPS, 2 = Support
    if include_roles:
        roles = rng.choice(ROLES, size=n_players, p=ROLE_PROBABILITIES)
    else:
        roles = [None] * n_players

    # 5. Ping ~ Lognormal(mean=3.5, sigma=0.5) (typical median ~33ms, tail 100+ ms)
    if include_ping:
        pings = rng.lognormal(mean=3.5, sigma=0.5, size=n_players)
    else:
        pings = [None] * n_players

    players: list[Player] = []
    for i in range(n_players):
        players.append(
            Player(
                id=i,
                skill=float(round(skills[i], 1)),
                wait=float(round(waits[i], 1)),
                arrival=float(round(arrivals[i], 1)),
                role=int(roles[i]) if roles[i] is not None else None,
                ping=float(round(pings[i], 1)) if pings[i] is not None else None,
            )
        )

    return Instance(
        players=players,
        k=match_k,
        dt=dt,
        max_wait=max_wait,
        gap0=gap0,
        gap_alpha=gap_alpha,
        seed=seed,
    )
